import shutil
import openpyxl
from openpyxl.styles import PatternFill
from fractions import Fraction

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

rows = list(range(2, 17))  # B2:B16

raw = []
for r in rows:
    v = vws.cell(row=r, column=1).value
    if v is None:
        v = 0
    raw.append(v)

def to_frac(x):
    if isinstance(x, Fraction):
        return x
    if isinstance(x, bool):
        return Fraction(int(x))
    if isinstance(x, int):
        return Fraction(x)
    if isinstance(x, float):
        return Fraction(str(x))
    return Fraction(str(x))

fracs = [to_frac(x) for x in raw]

pos = [f for f in fracs if f > 0]
neg = [f for f in fracs if f < 0]

max_pos = max(pos) if pos else Fraction(1)
min_neg = min(neg) if neg else Fraction(-1)
abs_min_neg = -min_neg if min_neg < 0 else Fraction(1)

scores = []
for f in fracs:
    if f > 0:
        scores.append(Fraction(5) * f / max_pos)
    elif f < 0:
        scores.append(Fraction(5) * f / abs_min_neg)
    else:
        scores.append(Fraction(0))

ranks = [1 + sum(1 for t in scores if t > s) for s in scores]

fill = PatternFill(start_color="FFA6A6A6", end_color="FFA6A6A6", fill_type="solid")
fmt_11 = "0." + "0" * 11

for i, r in enumerate(rows):
    s = scores[i]

    if s.denominator == 1:
        val = int(s)
        fmt = "0"
    elif (s * 10).denominator == 1:
        val = float(s)
        fmt = "0.0"
    else:
        val = float(s)
        fmt = fmt_11

    cell = ws.cell(row=r, column=2)
    cell.value = val
    cell.fill = fill
    cell.number_format = fmt

    ws.cell(row=r, column=3).value = ranks[i]

print("rows:", len(rows))
print("scores:", [round(float(s), 11) for s in scores])
print("ranks:", ranks)

wb.save(OUT)
